def split(line):
    out = []
    cur = ''
    started = False
    state = None  # None, "'" or '"'
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if state is None:
            if ch == "'":
                state = "'"
                started = True
                i += 1
            elif ch == '"':
                state = '"'
                started = True
                i += 1
            elif ch == '\\':
                if i + 1 < n:
                    cur += line[i + 1]
                    i += 2
                else:
                    cur += '\\'
                    i += 1
                started = True
            elif ch.isspace():
                if started:
                    out.append(cur)
                    cur = ''
                    started = False
                i += 1
            else:
                cur += ch
                started = True
                i += 1
        elif state == "'":
            if ch == "'":
                state = None
            else:
                cur += ch
            i += 1
        else:  # inside double quotes
            if ch == '"':
                state = None
                i += 1
            elif ch == '\\' and i + 1 < n and line[i + 1] in ('"', '\\'):
                cur += line[i + 1]
                i += 2
            else:
                cur += ch
                i += 1
    if state is not None:
        raise ValueError('unterminated quote')
    if started:
        out.append(cur)
    return out

